template <typename UnionPtrType>
GetVideoResultPtr GetVideoResult::Clone() const {
  switch (tag_) {
    case Tag::kVideo:
      return NewVideo(
          mojo::Clone(*data_.video));
    case Tag::kErrorMessage:
      return NewErrorMessage(
          mojo::Clone(*data_.error_message));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, GetVideoResult>::value>::type*>
bool GetVideoResult::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kVideo:
      return mojo::Equals(*(data_.video), *(other.data_.video));
    case Tag::kErrorMessage:
      return mojo::Equals(*(data_.error_message), *(other.data_.error_message));
  }

  return false;
}
